//! Corpus history in the bi-temporal provenance graph (VisionFlow ADR-2022).
//!
//! A full corpus sync rebuilds `urn:ngm:graph:ontology:assert` with
//! `CLEAR+INSERT`, which on its own keeps no history. This module records the
//! change as assertion-versions in the append-only provenance graph
//! (VisionClaw ADR-2016, legacy ADR-049), so `GET /api/ontology/state-at`
//! answers for authored content as well as for governed decisions.
//!
//! ## What is diffed
//!
//! The new corpus triple set is diffed against the **open versions this writer
//! owns**: those generated by a corpus-sync activity (URN prefix
//! [`CORPUS_SYNC_ACTIVITY_PREFIX`]). It is never diffed against `:assert`,
//! which also holds decision instances and governed mutations, so other
//! writers' versions are never closed or duplicated. A re-sync of an
//! unchanged corpus writes nothing.
//!
//! ## Scope
//!
//! - Only **public** pages (`public: true`, the same predicate the graph
//!   stream uses to withhold private nodes) and edges between them. Anything
//!   written here cannot be removed until VisionClaw ADR-2102 lands an erasure
//!   mechanism, so private content never enters.
//! - Only IRI-object triples: class typing and class relations, from
//!   [`ontology_graph_iri_triples`], the projection `save_ontology_graph` also
//!   writes. Labels and other literals are not versioned.
//!
//! ## Clocks
//!
//! Neither corpus source supplies a commit time (the local vault gives
//! `mtime:size`, GitHub a blob SHA), so valid time and recorded time are both
//! the sync instant. History therefore starts at the first sync with this
//! writer enabled, at the granularity of full syncs.
//!
//! ## Convergence (ADR-2022 P4)
//!
//! [`triple_digest`] hashes a sorted triple set. After a rebuild the sync
//! compares the digest of what it meant to write with the digest of what
//! `:assert` holds for those subjects, and the digest of the public set with
//! that of the open corpus versions, and reports any mismatch.

use std::collections::{BTreeSet, HashMap};

use chrono::{DateTime, SecondsFormat, Utc};
use oxigraph::model::{Quad, Term};
use oxigraph::sparql::QueryResults;
use oxigraph::store::Store;
use sha2::{Digest, Sha256};

use visionclaw_adapters::oxigraph_ontology_repository::ontology_graph_iri_triples;
use visionclaw_adapters::provenance_emitter::{build_activity_quads, ActivityRecord};
use visionclaw_domain::models::graph::GraphData;

use crate::services::provenance_writer::{
    build_assertion_version, build_retraction_update, AssertionInput, AssertionVersion, DL_NS,
    GRAPH_ASSERT, GRAPH_PROVENANCE,
};

/// Activity URN prefix that marks a version as owned by the corpus sync.
pub const CORPUS_SYNC_ACTIVITY_PREFIX: &str = "urn:visionclaw:execution:corpus-sync-";

/// Kill switch: set to `0`/`false`/`off` to stop recording corpus history.
pub const CORPUS_HISTORY_ENV: &str = "VISIONCLAW_CORPUS_HISTORY";

/// `(subject, predicate, object)`, all IRIs.
pub type Triple = (String, String, String);

/// Whether the kill switch leaves corpus history enabled (default on).
pub fn enabled_by_env() -> bool {
    !matches!(
        std::env::var(CORPUS_HISTORY_ENV)
            .ok()
            .as_deref()
            .map(str::trim),
        Some("0") | Some("false") | Some("off") | Some("no")
    )
}

/// The agent the corpus sync acts as: VisionClaw's own panel identity, the
/// key the ACSP producer and elevation actors already sign with. `None` when
/// no key is configured, in which case no history is written.
pub fn corpus_agent_iri() -> Option<String> {
    use nostr_sdk::prelude::{Keys, SecretKey};
    let secret = crate::services::acsp::key_file::load_panel_secret().ok()??;
    let keys = Keys::new(SecretKey::from_hex(secret.secret_hex()).ok()?);
    Some(format!("did:nostr:{}", keys.public_key().to_hex()))
}

/// Mint the activity URN for one sync at `at`.
pub fn corpus_sync_activity_urn(at: &DateTime<Utc>) -> String {
    format!(
        "{CORPUS_SYNC_ACTIVITY_PREFIX}{}",
        at.format("%Y%m%dT%H%M%SZ")
    )
}

/// The public part of `graph`: nodes whose metadata says `public: true`, and
/// the edges with both endpoints among them.
pub fn public_subgraph(graph: &GraphData) -> GraphData {
    let nodes: Vec<_> = graph
        .nodes
        .iter()
        .filter(|n| {
            n.metadata
                .get("public")
                .is_some_and(|v| v.eq_ignore_ascii_case("true"))
        })
        .cloned()
        .collect();
    let ids: std::collections::HashSet<u32> = nodes.iter().map(|n| n.id).collect();
    let edges = graph
        .edges
        .iter()
        .filter(|e| ids.contains(&e.source) && ids.contains(&e.target))
        .cloned()
        .collect();
    GraphData {
        nodes,
        edges,
        metadata: Default::default(),
        id_to_metadata: HashMap::new(),
    }
}

/// The IRI-object triple set `save_ontology_graph` writes for `graph`.
pub fn corpus_triples(graph: &GraphData) -> BTreeSet<Triple> {
    ontology_graph_iri_triples(graph).into_iter().collect()
}

/// SHA-256 (lowercase hex) over the sorted triples, one `<s> <p> <o> .\n` line
/// each. Equal sets give equal digests whatever order they were built in.
pub fn triple_digest<'a>(triples: impl IntoIterator<Item = &'a Triple>) -> String {
    let sorted: BTreeSet<&Triple> = triples.into_iter().collect();
    let mut hasher = Sha256::new();
    for (s, p, o) in sorted {
        hasher.update(format!("<{s}> <{p}> <{o}> .\n").as_bytes());
    }
    hex::encode(hasher.finalize())
}

fn term_str(term: Option<&Term>) -> Option<String> {
    match term? {
        Term::NamedNode(n) => Some(n.as_str().to_string()),
        Term::Literal(l) => Some(l.value().to_string()),
        _ => None,
    }
}

fn term_time(term: Option<&Term>) -> Option<DateTime<Utc>> {
    DateTime::parse_from_rfc3339(&term_str(term)?)
        .ok()
        .map(|d| d.with_timezone(&Utc))
}

/// The open (no `dl:validTo`) versions generated by a corpus-sync activity.
pub fn open_corpus_versions(store: &Store) -> Result<Vec<AssertionVersion>, String> {
    let sparql = format!(
        r#"PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX prov: <http://www.w3.org/ns/prov#>
PREFIX dl: <{DL_NS}>
SELECT ?entity ?subject ?predicate ?object ?validFrom ?generatedAt
WHERE {{
  GRAPH <{GRAPH_PROVENANCE}> {{
    ?entity a prov:Entity ;
            rdf:subject ?subject ;
            rdf:predicate ?predicate ;
            rdf:object ?object ;
            dl:validFrom ?validFrom ;
            prov:generatedAtTime ?generatedAt ;
            prov:wasGeneratedBy ?activity .
    FILTER ( STRSTARTS(STR(?activity), "{CORPUS_SYNC_ACTIVITY_PREFIX}") )
    FILTER NOT EXISTS {{ ?entity dl:validTo ?end }}
  }}
}}"#
    );
    let QueryResults::Solutions(solutions) = store
        .query(&sparql)
        .map_err(|e| format!("open corpus versions: {e}"))?
    else {
        return Ok(Vec::new());
    };
    let mut out = Vec::new();
    for row in solutions {
        let row = row.map_err(|e| format!("open corpus versions: {e}"))?;
        let (Some(entity_iri), Some(subject), Some(predicate), Some(object)) = (
            term_str(row.get("entity")),
            term_str(row.get("subject")),
            term_str(row.get("predicate")),
            term_str(row.get("object")),
        ) else {
            continue;
        };
        let (Some(valid_from), Some(generated_at)) = (
            term_time(row.get("validFrom")),
            term_time(row.get("generatedAt")),
        ) else {
            continue;
        };
        out.push(AssertionVersion {
            entity_iri,
            subject,
            predicate,
            object,
            valid_from,
            valid_to: None,
            generated_at,
        });
    }
    Ok(out)
}

/// The triples `:assert` currently holds with an IRI object and a subject in
/// `subjects`, restricted to `predicates`.
pub fn assert_triples_for(
    store: &Store,
    subjects: &BTreeSet<String>,
    predicates: &BTreeSet<String>,
) -> Result<BTreeSet<Triple>, String> {
    let sparql = format!(
        "SELECT ?s ?p ?o WHERE {{ GRAPH <{GRAPH_ASSERT}> {{ ?s ?p ?o . FILTER(isIRI(?o)) }} }}"
    );
    let QueryResults::Solutions(solutions) = store
        .query(&sparql)
        .map_err(|e| format!("assert triples: {e}"))?
    else {
        return Ok(BTreeSet::new());
    };
    let mut out = BTreeSet::new();
    for row in solutions {
        let row = row.map_err(|e| format!("assert triples: {e}"))?;
        let (Some(s), Some(p), Some(o)) = (
            term_str(row.get("s")),
            term_str(row.get("p")),
            term_str(row.get("o")),
        ) else {
            continue;
        };
        if subjects.contains(&s) && predicates.contains(&p) {
            out.insert((s, p, o));
        }
    }
    Ok(out)
}

/// The provenance quads one sync will append.
#[derive(Debug, Default)]
pub struct HistoryPlan {
    /// Quads for newly opened versions, plus the sync activity record.
    pub quads: Vec<Quad>,
    /// Versions opened (triples new since the last sync).
    pub opened: usize,
    /// Versions closed (triples gone since the last sync).
    pub closed: usize,
    /// Triples skipped because a term was not a valid IRI.
    pub skipped: usize,
}

impl HistoryPlan {
    /// True when this sync changes nothing.
    pub fn is_empty(&self) -> bool {
        self.opened == 0 && self.closed == 0
    }
}

/// Plan the history append for `current` against the writer's `open` versions.
///
/// Every open version whose triple is gone is closed at `now` (an added
/// `dl:validTo`, nothing deleted); every new triple opens a version valid from
/// `now`. A triple with two open versions keeps the earliest and closes the
/// rest, restoring one open version per triple. Pure: no store access.
pub fn plan_history(
    current: &BTreeSet<Triple>,
    open: &[AssertionVersion],
    now: DateTime<Utc>,
    agent_iri: &str,
) -> HistoryPlan {
    let activity_urn = corpus_sync_activity_urn(&now);
    let mut plan = HistoryPlan::default();

    let mut sorted: Vec<&AssertionVersion> = open.iter().collect();
    sorted.sort_by(|a, b| (a.valid_from, &a.entity_iri).cmp(&(b.valid_from, &b.entity_iri)));
    let mut kept: BTreeSet<Triple> = BTreeSet::new();
    for v in sorted {
        let triple = (v.subject.clone(), v.predicate.clone(), v.object.clone());
        if current.contains(&triple) && kept.insert(triple) {
            continue;
        }
        match build_retraction_update(&v.entity_iri, &v.subject, &v.predicate, &v.object, &now) {
            Ok(r) => {
                plan.quads.push(r.closing_quad);
                plan.closed += 1;
            }
            Err(_) => plan.skipped += 1,
        }
    }

    for (s, p, o) in current.difference(&kept) {
        match build_assertion_version(&AssertionInput {
            subject: s.clone(),
            predicate: p.clone(),
            object: o.clone(),
            valid_from: now,
            valid_to: None,
            generated_at: now,
            activity_urn: activity_urn.clone(),
            agent_iri: agent_iri.to_string(),
        }) {
            Ok(v) => {
                plan.quads.extend(v.provenance_quads);
                plan.opened += 1;
            }
            Err(_) => plan.skipped += 1,
        }
    }

    if !plan.is_empty() {
        let record = ActivityRecord {
            activity_urn,
            agent_did: agent_iri.to_string(),
            timestamp: now.to_rfc3339_opts(SecondsFormat::Secs, true),
            action: "ingest".to_string(),
            derivation: "asserted".to_string(),
            used: None,
            generated: None,
            informed_by: None,
        };
        match build_activity_quads(&record) {
            Ok(q) => plan.quads.extend(q),
            Err(_) => plan.skipped += 1,
        }
    }
    plan
}

/// Append `plan` to the provenance graph in one transaction (all or nothing).
/// Inserts only; never deletes.
pub fn apply_history(store: &Store, plan: &HistoryPlan) -> Result<usize, String> {
    if plan.quads.is_empty() {
        return Ok(0);
    }
    store
        .transaction(|mut txn| {
            for quad in &plan.quads {
                txn.insert(quad.as_ref())?;
            }
            Ok::<_, oxigraph::store::StorageError>(plan.quads.len())
        })
        .map_err(|e| format!("append corpus history: {e}"))
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::services::provenance_writer::state_at;
    use chrono::TimeZone;
    use oxigraph::model::{GraphNameRef, NamedNodeRef};
    use visionclaw_domain::models::edge::Edge;
    use visionclaw_domain::models::node::Node;

    const AGENT: &str =
        "did:nostr:bbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbb";
    const SUB: &str = "http://www.w3.org/2000/01/rdf-schema#subClassOf";

    fn t(h: u32) -> DateTime<Utc> {
        Utc.with_ymd_and_hms(2026, 11, 3, h, 0, 0).unwrap()
    }

    fn node(id: u32, slug: &str, public: bool) -> Node {
        let mut n = Node::new_with_id(slug.to_string(), Some(id));
        n.owl_class_iri = Some(format!("urn:ngm:class:{slug}"));
        if public {
            n.metadata.insert("public".to_string(), "true".to_string());
        }
        n
    }

    fn sub_edge(src: u32, tgt: u32) -> Edge {
        let mut e = Edge::new(src, tgt, 1.0);
        e.edge_type = Some("is_subclass_of".to_string());
        e
    }

    fn graph(nodes: Vec<Node>, edges: Vec<Edge>) -> GraphData {
        GraphData {
            nodes,
            edges,
            metadata: Default::default(),
            id_to_metadata: HashMap::new(),
        }
    }

    fn provenance_len(store: &Store) -> usize {
        let g = NamedNodeRef::new_unchecked(GRAPH_PROVENANCE);
        store
            .quads_for_pattern(None, None, None, Some(GraphNameRef::NamedNode(g)))
            .count()
    }

    /// Run one sync of `g` at `now` against `store`; returns the plan.
    fn sync(store: &Store, g: &GraphData, now: DateTime<Utc>) -> HistoryPlan {
        let current = corpus_triples(&public_subgraph(g));
        let open = open_corpus_versions(store).unwrap();
        let plan = plan_history(&current, &open, now, AGENT);
        apply_history(store, &plan).unwrap();
        plan
    }

    fn all_versions(store: &Store) -> Vec<AssertionVersion> {
        // Reconstruct every corpus version (open or closed) for state_at checks.
        let sparql = format!(
            r#"PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX prov: <http://www.w3.org/ns/prov#>
PREFIX dl: <{DL_NS}>
SELECT ?e ?s ?p ?o ?f ?t ?g WHERE {{ GRAPH <{GRAPH_PROVENANCE}> {{
  ?e rdf:subject ?s ; rdf:predicate ?p ; rdf:object ?o ; dl:validFrom ?f ;
     prov:generatedAtTime ?g . OPTIONAL {{ ?e dl:validTo ?t }} }} }}"#
        );
        let QueryResults::Solutions(rows) = store.query(&sparql).unwrap() else {
            panic!()
        };
        rows.map(|r| {
            let r = r.unwrap();
            AssertionVersion {
                entity_iri: term_str(r.get("e")).unwrap(),
                subject: term_str(r.get("s")).unwrap(),
                predicate: term_str(r.get("p")).unwrap(),
                object: term_str(r.get("o")).unwrap(),
                valid_from: term_time(r.get("f")).unwrap(),
                valid_to: term_time(r.get("t")),
                generated_at: term_time(r.get("g")).unwrap(),
            }
        })
        .collect()
    }

    #[test]
    fn first_sync_opens_a_version_per_public_triple_and_skips_private_pages() {
        let store = Store::new().unwrap();
        let g = graph(
            vec![
                node(1, "camera", true),
                node(2, "device", true),
                node(3, "diary", false),
            ],
            vec![sub_edge(1, 2), sub_edge(3, 2)],
        );
        let plan = sync(&store, &g, t(9));
        // 2 public classes x 2 type triples + 1 public edge.
        assert_eq!(plan.opened, 5);
        assert_eq!(plan.closed, 0);
        let open = open_corpus_versions(&store).unwrap();
        assert!(open.iter().all(|v| !v.subject.ends_with(":diary")));
        assert!(open
            .iter()
            .all(|v| v.valid_from == t(9) && v.generated_at == t(9)));
    }

    #[test]
    fn resyncing_an_unchanged_corpus_writes_nothing() {
        let store = Store::new().unwrap();
        let g = graph(
            vec![node(1, "camera", true), node(2, "device", true)],
            vec![sub_edge(1, 2)],
        );
        sync(&store, &g, t(9));
        let before = provenance_len(&store);
        let plan = sync(&store, &g, t(10));
        assert!(plan.is_empty());
        assert!(plan.quads.is_empty());
        assert_eq!(provenance_len(&store), before);
    }

    #[test]
    fn a_moved_edge_closes_one_version_and_opens_one_and_state_at_sees_both_sides() {
        let store = Store::new().unwrap();
        let nodes = vec![
            node(1, "camera", true),
            node(2, "device", true),
            node(3, "sensor", true),
        ];
        sync(&store, &graph(nodes.clone(), vec![sub_edge(1, 2)]), t(9));
        let before = provenance_len(&store);
        let plan = sync(&store, &graph(nodes, vec![sub_edge(1, 3)]), t(12));
        assert_eq!((plan.opened, plan.closed), (1, 1));
        assert!(provenance_len(&store) > before, "provenance only grows");

        let versions = all_versions(&store);
        let parent_at = |h| {
            state_at(&versions, t(h))
                .into_iter()
                .filter(|v| v.predicate == SUB)
                .map(|v| v.object.clone())
                .collect::<Vec<_>>()
        };
        assert_eq!(parent_at(10), vec!["urn:ngm:class:device".to_string()]);
        // Half-open: at the instant of the move exactly one parent is current.
        assert_eq!(parent_at(12), vec!["urn:ngm:class:sensor".to_string()]);
    }

    #[test]
    fn versions_from_other_writers_are_never_closed() {
        let store = Store::new().unwrap();
        // A governed decision version on the same agent, different activity.
        let decision = build_assertion_version(&AssertionInput {
            subject: "urn:visionclaw:decision:d1".to_string(),
            predicate: "http://www.w3.org/1999/02/22-rdf-syntax-ns#type".to_string(),
            object: format!("{DL_NS}DecisionRecord"),
            valid_from: t(8),
            valid_to: None,
            generated_at: t(8),
            activity_urn: "urn:visionclaw:execution:decision-1".to_string(),
            agent_iri: AGENT.to_string(),
        })
        .unwrap();
        store
            .extend(decision.provenance_quads.iter().cloned())
            .unwrap();

        let plan = sync(&store, &graph(vec![node(1, "camera", true)], vec![]), t(9));
        assert_eq!(plan.closed, 0);
        let open = open_corpus_versions(&store).unwrap();
        assert!(open.iter().all(|v| v.entity_iri != decision.entity_iri));
        let closed = all_versions(&store)
            .into_iter()
            .find(|v| v.entity_iri == decision.entity_iri)
            .unwrap();
        assert_eq!(closed.valid_to, None);
    }

    #[test]
    fn duplicate_open_versions_collapse_to_the_earliest() {
        let store = Store::new().unwrap();
        let g = graph(vec![node(1, "camera", true)], vec![]);
        sync(&store, &g, t(9));
        // Force a second open version of the same triples (as a crash-replay might).
        let current = corpus_triples(&public_subgraph(&g));
        let dup = plan_history(&current, &[], t(10), AGENT);
        apply_history(&store, &dup).unwrap();
        let plan = sync(&store, &g, t(11));
        assert_eq!((plan.opened, plan.closed), (0, 2));
        let open = open_corpus_versions(&store).unwrap();
        assert_eq!(open.len(), 2);
        assert!(open.iter().all(|v| v.valid_from == t(9)));
    }

    #[test]
    fn digest_is_order_independent_and_matches_open_versions() {
        let store = Store::new().unwrap();
        let g = graph(
            vec![node(1, "camera", true), node(2, "device", true)],
            vec![sub_edge(1, 2)],
        );
        sync(&store, &g, t(9));
        let expected = corpus_triples(&public_subgraph(&g));
        let from_history: BTreeSet<Triple> = open_corpus_versions(&store)
            .unwrap()
            .into_iter()
            .map(|v| (v.subject, v.predicate, v.object))
            .collect();
        assert_eq!(triple_digest(&expected), triple_digest(&from_history));
        let reversed: Vec<Triple> = expected.iter().rev().cloned().collect();
        assert_eq!(triple_digest(&expected), triple_digest(&reversed));
    }

    #[test]
    fn kill_switch_values() {
        // Only checks parsing; the env var is process-global, so restore it.
        let prior = std::env::var(CORPUS_HISTORY_ENV).ok();
        std::env::set_var(CORPUS_HISTORY_ENV, "off");
        assert!(!enabled_by_env());
        std::env::set_var(CORPUS_HISTORY_ENV, "1");
        assert!(enabled_by_env());
        match prior {
            Some(v) => std::env::set_var(CORPUS_HISTORY_ENV, v),
            None => std::env::remove_var(CORPUS_HISTORY_ENV),
        }
    }
}
